C.startFromPhoto = (url, name) => { const im = C.img(url); const go = () => { let w = im.naturalWidth || 3000, h = im.naturalHeight || 3000; const k = Math.min(1, 4000 / Math.max(w, h)); w = Math.max(64, Math.round(w * k)); h = Math.max(64, Math.round(h * k)); C.begin(); C.art.name = (name || 'Photo').replace(/\.[a-z0-9]+$/i, ''); C.art.w = w; C.art.h = h; C.art.layers = []; C.art.global = { look: 'none' }; const b = add(C.art, { type: 'image', name: 'Background', url, fit: 'fill', scale: 1, crop: { l: 0, r: 0, t: 0, b: 0 } }); C.sel = b.id; C.commit(); C.size(); PX.toast('Your photo is the canvas: add text, stickers, filters, drawings and frames on top.'); }; if (im.complete && im.naturalWidth) go(); else { im.addEventListener('load', go, { once: true }); im.addEventListener('error', () => PX.toast('That picture could not be opened.', true), { once: true }); } };
PX.on('artImported', m => { if (C._cellFill) return; if (C._startPhoto) { C._startPhoto = false; C.startFromPhoto(m.url, m.name); return; } if (C._bgPhoto) { C._bgPhoto = false; C.setBackground({ type: 'image', url: m.url, fit: 'fill', x: 0, y: 0, scale: 1 }); return; } C.addLayer({ type: 'image', name: m.name || 'Photo', url: m.url, fit: 'fit', scale: 0.8, crop: { l: 0, r: 0, t: 0, b: 0 } }); });
